import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define WARP_SIZE 32
#define ROWS_PER_BLOCK 8
#define TILE_K4 512
#define BLOCK_THREADS 256
#define SPLIT_K 8
__global__ void matvec_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int K) {
    int block_row0 = blockIdx.x * ROWS_PER_BLOCK;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int K4 = K / 4;
    int total_splits = gridDim.y;
    int split_id = blockIdx.y;
    int K4_per_split = (K4 + total_splits - 1) / total_splits;
    int k4_start = split_id * K4_per_split;
    int k4_end = min(k4_start + K4_per_split, K4);
    int local_len = (k4_end > k4_start) ? (k4_end - k4_start) : 0;
    const float4* B_vec = reinterpret_cast<const float4*>(B);
    __shared__ float4 sB[2][TILE_K4];
    float sum[ROWS_PER_BLOCK];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) sum[r] = 0.0f;
    const float4* A_row_ptr[ROWS_PER_BLOCK];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
        int row = block_row0 + r;
        if (row < M) {
            A_row_ptr[r] = reinterpret_cast<const float4*>(A + (size_t)row * K);
        } else {
            A_row_ptr[r] = nullptr;
        }
    }
    int num_tiles = (local_len + TILE_K4 - 1) / TILE_K4;
    if (num_tiles > 0) {
        int first_len = min(TILE_K4, local_len);
        for (int i = tid; i < first_len; i += nthreads) {
            sB[0][i] = B_vec[k4_start + i];
        }
        __syncthreads();
        int buf = 0;
        for (int t = 0; t < num_tiles; ++t) {
            int cur_tile_start = t * TILE_K4;
            int cur_tile_len = min(TILE_K4, local_len - cur_tile_start);
            int next_buf = buf ^ 1;
            int next_tile_start = cur_tile_start + TILE_K4;
            int next_tile_len = (next_tile_start < local_len) ? min(TILE_K4, local_len - next_tile_start) : 0;
            if (next_tile_len > 0) {
                for (int i = tid; i < next_tile_len; i += nthreads) {
                    sB[next_buf][i] = B_vec[k4_start + next_tile_start + i];
                }
            }
            #pragma unroll
            for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
                if (A_row_ptr[r] == nullptr) continue;
                const float4* A_row = A_row_ptr[r];
                for (int i = tid; i < cur_tile_len; i += nthreads) {
                    float4 a = A_row[k4_start + cur_tile_start + i];
                    float4 b = sB[buf][i];
                    sum[r] += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
            }
            __syncthreads();
            buf = next_buf;
        }
    }
    // remainder (K not divisible by 4) handled only by the last split
    if (split_id == total_splits - 1) {
        int rem_start = K4 * 4;
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
            int row = block_row0 + r;
            if (row >= M) continue;
            for (int i = rem_start + tid; i < K; i += nthreads) {
                sum[r] += A[(size_t)row * K + i] * B[i];
            }
        }
    }
    // warp-level reduction per row
    unsigned mask = 0xffffffff;
    int lane = tid % WARP_SIZE;
    int warp_id = tid / WARP_SIZE;
    int num_warps = (nthreads + WARP_SIZE - 1) / WARP_SIZE;
    __shared__ float warp_sums[ROWS_PER_BLOCK][32];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
        float v = sum[r];
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            v += __shfl_down_sync(mask, v, offset);
        }
        if (lane == 0) {
            warp_sums[r][warp_id] = v;
        }
    }
    __syncthreads();
    if (warp_id == 0) {
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
            float val = (lane < num_warps) ? warp_sums[r][lane] : 0.0f;
            for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
                val += __shfl_down_sync(mask, val, offset);
            }
            if (lane == 0) {
                int row = block_row0 + r;
                if (row < M) {
                    atomicAdd(&C[row], val);
                }
            }
        }
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    auto C = torch::zeros({M, 1}, A.options());
    const int threads = BLOCK_THREADS;
    const int blocks_x = (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    dim3 grid(blocks_x, SPLIT_K);
    matvec_kernel<<<grid, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );
    return C;
}
"""

cpp_source = r"""
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

matvec_module = load_inline(
    name="matvec_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matvec_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matvec = matvec_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda or A.dtype != torch.float32:
            A = A.to(device='cuda', dtype=torch.float32, non_blocking=True)
        if not B.is_cuda or B.dtype != torch.float32:
            B = B.to(device='cuda', dtype=torch.float32, non_blocking=True)
        return self.matvec.matvec_cuda(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, 1)
    return [A, B]


def get_init_inputs():
    return []

